/**
 * @fileoverview Test the usage of private methods
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-private-method-call'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-private-method-call', rule, {

    valid: [
        {
            settings: {
                extjs: {
                    version: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomClass', {});
            `
        }
    ],

    invalid: [
        {
            settings: {
                extjs: {
                    version: '7.9.0'
                }
            },
            code: `
                Ext.ClassManager.create('MyCustomClass', {});
            `,
            errors: [
                { message: /Call to private method 'create' found for 'Ext.ClassManager'/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9'
                }
            },
            code: `
                Ext.define('MyCustomButton', {
                    extend: 'Ext.button.Button',
                    initComponent: function () {
                        var hasIcon = this._hasIcon();
                    }
                });

                var btn1 = Ext.create('Ext.button.Button');
                console.log(btn1._hasIcon());

                var btn2 = Ext.create({xclass: 'Ext.button.Button'});
                console.log(btn2._hasIcon());

                var btn3 = Ext.widget('button');
                console.log(btn3._hasIcon());

                var btn4 = Ext.createWidget('button');
                console.log(btn4._hasIcon());

                Ext.widget('button')._hasIcon();

                Ext.define('SimpleTasks.ux.DropZone', {
                    extend: 'Ext.tree.ViewDropZone',
                    handleNodeDrop : function(data, overRecord, position) {
                        var droppedRecord = data.records[0],
                            me = this;

                        if(droppedRecord instanceof SimpleTasks.model.Task) {
                            me.cancelExpand();
                            this.fireViewEvent('taskdrop', droppedRecord, overRecord);          // fireViewEvent is an undocumented method
                        } else if(droppedRecord instanceof SimpleTasks.model.List) {
                            this.callParent(arguments);
                            this.fireViewEvent('listdrop', droppedRecord, overRecord, position);
                        }
                    }
                });
                // TODO - add support for knowing that 'cancelExpand' and 'fireViewEvent' is
                // running under the scope of Ext.trree.ViewDropZone due to the xclass config
                Ext.create({
                    xclass: 'Ext.tree.ViewDropZone',
                    handleNodeDrop : function(data, overRecord, position) {
                        var droppedRecord = data.records[0],
                            me = this;

                        if(droppedRecord instanceof SimpleTasks.model.Task) {
                            me.cancelExpand();
                            //this.fireViewEvent('taskdrop', droppedRecord, overRecord);          // fireViewEvent is an undocumented method
                        } else if(droppedRecord instanceof SimpleTasks.model.List) {
                            this.callParent(arguments);
                            //this.fireViewEvent('listdrop', droppedRecord, overRecord, position);
                        }
                    }
                });
            `,
            errors: [
                { message: /Call to private method '_hasIcon' found for 'Ext.button.Button'/ },
                { message: /Call to private method '_hasIcon' found for 'Ext.button.Button'/ },
                { message: /Call to private method '_hasIcon' found for 'Ext.button.Button'/ },
                { message: /Call to private method '_hasIcon' found for 'Ext.button.Button'/ },
                { message: /Call to private method 'createWidget' found for 'Ext'/ },
                { message: /Call to private method '_hasIcon' found for 'Ext.button.Button'/ },
                { message: /Call to private method '_hasIcon' found for 'Ext.button.Button'/ },
                { message: /Call to private method 'cancelExpand' found for 'Ext.tree.ViewDropZone'/ },
                //{ message: /Call to private method 'fireViewEvent' found for 'Ext.tree.ViewDropZone'/ },
                //{ message: /Call to private method 'fireViewEvent' found for 'Ext.tree.ViewDropZone'/ }
            ]
        }
    ]
});
